custom_css:
/* MoodTube theme: Stamp: Trick or Treat. A Halloween postage stamp: perforated paper frame, black picture, pink and dusty blue. */
@import url('https://fonts.googleapis.com/css2?family=Old+Standard+TT:wght@400;700&display=swap');

/* palette: --t-frame is the stamp paper, --t-alt the second colour, --t-pink the Play fill */
.mt-player, #mt-settings-modal, .mt-fab, .mt-pl-modal, #moodtube-dock {
  --t-ink: #141014;
  --t-ink2: #221a20;
  --t-pink: #f2a8b8;
  --t-pink2: #f7c3cf;
  --t-blue: #9fb4d6;
  --t-blue2: #2b2f40;
  --t-line: color-mix(in srgb, var(--t-frame) 35%, transparent);
  --t-line2: color-mix(in srgb, var(--t-frame) 14%, transparent);
  --mt-bg-primary: var(--t-ink);
  --mt-bg-secondary: var(--t-ink2);
  --mt-bg-input: var(--t-ink2);
  --mt-accent: var(--t-frame);
  --mt-accent-hover: var(--t-pink2);
  --mt-border: var(--t-line);
  --mt-text: var(--t-frame);
  --mt-text-dim: var(--t-alt);
  --mt-text-on-accent: var(--t-ink);
  --mt-text-strong: var(--t-frame);
  --mt-divider: var(--t-line2);
  --mt-overlay: rgba(10, 6, 10, 0.78);
  --mt-modal-shadow: none;
  --mt-pl-spotify-tab: var(--t-frame);
  --mt-pl-spotify-tab-text: var(--t-ink);
  --t-perf:
    radial-gradient(circle at 50% 0, #0000 4.5px, #000 5px) 0 0 / 12px 12px round no-repeat,
    radial-gradient(circle at 50% 100%, #0000 4.5px, #000 5px) 0 100% / 12px 12px round no-repeat,
    radial-gradient(circle at 0 50%, #0000 4.5px, #000 5px) 0 0 / 12px 12px no-repeat round,
    radial-gradient(circle at 100% 50%, #0000 4.5px, #000 5px) 100% 0 / 12px 12px no-repeat round,
    linear-gradient(#000 0 0) 6px 6px / calc(100% - 12px) calc(100% - 12px) no-repeat;
}

.mt-progress {
  --mt-slider-track: color-mix(in srgb, var(--t-frame) 22%, transparent);
  --mt-slider-track-height: 2px;
  --mt-slider-track-radius: 0px;
  --mt-slider-progress: var(--t-frame);
  --mt-slider-thumb-size: 10px;
  --mt-slider-thumb-bg: var(--t-pink);
  --mt-slider-thumb-bg-hover: var(--t-pink2);
  --mt-slider-thumb-border: 2px solid var(--t-ink);
  --mt-slider-thumb-radius: 50%;
  --mt-slider-thumb-shadow: none;
}
.mt-volume {
  --mt-slider-track: color-mix(in srgb, var(--t-alt) 22%, transparent);
  --mt-slider-track-height: 2px;
  --mt-slider-track-radius: 0px;
  --mt-slider-progress: var(--t-alt);
  --mt-slider-thumb-size: 8px;
  --mt-slider-thumb-bg: var(--t-alt);
  --mt-slider-thumb-bg-hover: var(--t-pink2);
  --mt-slider-thumb-border: none;
  --mt-slider-thumb-radius: 50%;
  --mt-slider-thumb-shadow: none;
}

/* the stamp: paper frame with perforated edges, black picture inside */
.mt-player {
  container-type: size;
  padding: 40px 24px 32px;
  background: var(--t-frame);
  border: none;
  border-radius: 0;
  box-shadow: none;
  backdrop-filter: none;
  color: var(--t-frame);
  font-family: 'Old Standard TT', Georgia, serif;
  -webkit-mask: var(--t-perf);
  mask: var(--t-perf);
}
.mt-player * { font-family: inherit; }
.mt-player i { font-family: 'Font Awesome 6 Free', 'Font Awesome 5 Free', FontAwesome; }

#moodtube-mini-player, #moodtube-mini-player *, #mt-settings-modal, #mt-settings-modal *, .mt-fab, .mt-fab *, .mt-pl-modal, .mt-pl-modal *, #moodtube-dock, #moodtube-dock * {
  text-shadow: none;
}

.mt-slot-bg { inset: 14px; background: var(--t-pic); }

/* bottom inscriptions inside the picture */
.mt-slot-scene::before {
  position: absolute;
  left: 24px;
  bottom: 18px;
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 0.2em;
  color: var(--t-frame);
}

.mt-player-header { top: 22px; left: 24px; right: 96px; align-items: flex-start; }
.mt-player-status { display: none; }

.mt-window-btn {
  top: 22px;
  width: 20px;
  height: 20px;
  padding: 0;
  font-size: 12px;
  line-height: 1;
  display: flex;
  align-items: center;
  justify-content: center;
  box-sizing: border-box;
  color: var(--t-frame);
  cursor: pointer;
  transition: color 0.15s;
}
.mt-window-btn:hover { color: #fff; }
.mt-window-btn.mt-btn-close { right: 24px; }
.mt-window-btn.mt-btn-settings { right: 46px; }
.mt-window-btn.mt-btn-search { right: 68px; }
.mt-btn-search.mt-is-open { color: #fff !important; }

.mt-player-body { gap: 7px; justify-content: flex-start; }
.mt-cover-hole { display: none; }

.mt-track-info { padding: 0 24px; }
#moodtube-mini-player .mt-track-title {
  font-size: 19px;
  font-weight: 700;
  line-height: 1.15;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: var(--t-title);
}
.mt-track-subtitle { margin-top: 1px; font-size: 10px; font-weight: 400; letter-spacing: 0.22em; text-transform: uppercase; color: var(--t-alt); }
.mt-btn-favorite {
  top: 50%;
  right: 0;
  translate: 0 -50%;
  width: 20px;
  height: 20px;
  padding: 0;
  font-size: 13px;
  display: flex;
  align-items: center;
  justify-content: center;
  color: color-mix(in srgb, var(--t-frame) 55%, transparent);
  cursor: pointer;
}
.mt-btn-favorite:hover, .mt-btn-favorite.mt-is-active { color: var(--t-pink); }

.mt-progress { gap: 6px; margin-top: 0; }
.mt-time-current, .mt-time-total { font-size: 10px; letter-spacing: 0.05em; color: var(--t-alt); }

/* buttons: thin rings, Play is a filled pink circle */
.mt-controls { gap: 8px; justify-content: center; }
.mt-controls > .mt-btn {
  width: 30px;
  height: 30px;
  font-size: 12px;
  padding: 0;
  line-height: 1;
  box-sizing: border-box;
  flex-shrink: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  border-radius: 50%;
  background: transparent;
  border: 1.3px solid var(--t-frame);
  color: var(--t-frame);
  cursor: pointer;
  transition: background-color 0.15s, color 0.15s, translate 0.1s;
}
.mt-controls > .mt-btn:hover { background: var(--t-frame); color: var(--t-ink); }
.mt-controls > .mt-btn:active { translate: 0 1px; }
.mt-controls > .mt-btn.mt-btn-play, .mt-controls > #moodtube-btn-playpause {
  width: 38px;
  height: 38px;
  font-size: 15px;
  background: var(--t-pink);
  border-color: var(--t-pink);
  color: var(--t-ink);
}
.mt-controls > .mt-btn.mt-btn-play:hover, .mt-controls > #moodtube-btn-playpause:hover { background: var(--t-pink2); border-color: var(--t-pink2); }
#moodtube-btn-playpause.fa-play { padding-left: 2px; }
.mt-controls > .mt-btn.mt-btn-ai.mt-is-busy { background: var(--t-pink); border-color: var(--t-pink); color: var(--t-ink); animation: mt-st-blink 0.9s steps(2) infinite; }
@keyframes mt-st-blink { 50% { opacity: 0.5; } }

.mt-volume { gap: 6px; width: 86%; }
.mt-volume-low, .mt-volume-high, .mt-volume-icon { font-size: 10px; color: var(--t-alt); }

/* panels: same stamp, the queue is a sheet of small stamps */
.mt-panel {
  background: var(--t-pic);
  border: 14px solid var(--t-frame);
  padding: 30px 12px 12px;
  border-radius: 0;
  color: var(--t-frame);
}
.mt-panel-search { --mt-bg-primary: var(--t-pic); }
.mt-panel-header { border-bottom: 1px solid var(--t-line); padding-bottom: 6px; }
.mt-panel-header-left { margin-right: 24px; }
.mt-panel-title { font-size: 11px; font-weight: 700; letter-spacing: 0.05em; text-transform: uppercase; color: var(--t-frame); }
.mt-panel-close { color: var(--t-frame); }
.mt-panel-close:hover { color: #fff; }

.mt-queue-item { position: relative; gap: 8px; padding: 6px 4px; margin-bottom: 4px; border-radius: 0; background: transparent; border: 1px solid transparent; border-bottom-color: var(--t-line2); }
.mt-queue-item:hover { background: color-mix(in srgb, var(--t-frame) 10%, transparent); }
.mt-queue-item.mt-is-current { background: color-mix(in srgb, var(--t-frame) 14%, transparent); border-color: var(--t-line); }
.mt-queue-thumb, .mt-pl-cover {
  width: 30px;
  height: 30px;
  padding: 3px;
  box-sizing: border-box;
  border-radius: 0;
  object-fit: cover;
  background: var(--t-frame);
  -webkit-mask:
    radial-gradient(circle at 50% 0, #0000 1.6px, #000 2px) 0 0 / 5.5px 5.5px round no-repeat,
    radial-gradient(circle at 50% 100%, #0000 1.6px, #000 2px) 0 100% / 5.5px 5.5px round no-repeat,
    radial-gradient(circle at 0 50%, #0000 1.6px, #000 2px) 0 0 / 5.5px 5.5px no-repeat round,
    radial-gradient(circle at 100% 50%, #0000 1.6px, #000 2px) 100% 0 / 5.5px 5.5px no-repeat round,
    linear-gradient(#000 0 0) 2.5px 2.5px / calc(100% - 5px) calc(100% - 5px) no-repeat;
  mask:
    radial-gradient(circle at 50% 0, #0000 1.6px, #000 2px) 0 0 / 5.5px 5.5px round no-repeat,
    radial-gradient(circle at 50% 100%, #0000 1.6px, #000 2px) 0 100% / 5.5px 5.5px round no-repeat,
    radial-gradient(circle at 0 50%, #0000 1.6px, #000 2px) 0 0 / 5.5px 5.5px no-repeat round,
    radial-gradient(circle at 100% 50%, #0000 1.6px, #000 2px) 100% 0 / 5.5px 5.5px no-repeat round,
    linear-gradient(#000 0 0) 2.5px 2.5px / calc(100% - 5px) calc(100% - 5px) no-repeat;
}
.mt-queue-thumb.mt-is-empty { background: var(--t-frame); }
/* the current track is cancelled with a postmark */
.mt-queue-item.mt-is-current::after {
  content: '';
  position: absolute;
  left: 2px;
  top: 50%;
  translate: 0 -50%;
  width: 46px;
  height: 22px;
  background: url("data:image/svg+xml,%3Csvg%20xmlns%3D%27http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg%27%20viewBox%3D%270%200%2084%2028%27%3E%3Cg%20fill%3D%27none%27%20stroke%3D%27%23141014%27%20stroke-width%3D%271.6%27%20stroke-linecap%3D%27round%27%3E%3Cpath%20d%3D%27M2%206q8-5%2016%200t16%200%2016%200%2016%200%2016%200%27%2F%3E%3Cpath%20d%3D%27M2%2014q8-5%2016%200t16%200%2016%200%2016%200%2016%200%27%2F%3E%3Cpath%20d%3D%27M2%2022q8-5%2016%200t16%200%2016%200%2016%200%2016%200%27%2F%3E%3C%2Fg%3E%3C%2Fsvg%3E") center / contain no-repeat;
  pointer-events: none;
}
.mt-queue-title { color: var(--t-frame); font-size: 11.5px; letter-spacing: 0; }
.mt-queue-item.mt-is-current .mt-queue-title { color: #fff; }
.mt-queue-now { color: var(--t-pink); }
.mt-queue-add { color: var(--t-alt); }
.mt-queue-add:hover { color: #fff; }
.mt-queue-dislike { background-color: var(--t-alt); }
.mt-queue-dislike:hover { background-color: var(--t-pink); }
.mt-queue-empty { color: var(--t-alt); }

.mt-pl-tabs { border-bottom: 1px solid var(--t-line); gap: 6px; }
.mt-pl-tab { font-size: 11px; font-weight: 700; letter-spacing: 0.08em; text-transform: uppercase; color: var(--t-frame); background: transparent; border: 1.2px solid var(--t-frame); border-radius: 0; }
.mt-pl-tab.mt-is-active { background: var(--t-frame); color: var(--t-ink); }
.mt-playlist-item { border-radius: 0; border-bottom: 1px solid var(--t-line2); }
.mt-playlist-item:hover { background: color-mix(in srgb, var(--t-frame) 10%, transparent); }
.mt-playlist-title { color: var(--t-frame); font-weight: 700; }
.mt-pl-count { color: var(--t-alt); }
.mt-pl-tool { background: transparent; color: var(--t-frame); border: 1.2px solid var(--t-frame); border-radius: 0; }
.mt-pl-tool.mt-pl-play, .mt-pl-tool:hover { background: var(--t-pink); border-color: var(--t-pink); color: var(--t-ink); }

#moodtube-search-input { background: var(--t-ink2); color: var(--t-frame); border: 1px solid var(--t-frame); border-radius: 0; }
#moodtube-search-go { background: var(--t-pink); color: var(--t-ink); border: none; border-radius: 0; }
#moodtube-search-go:hover { background: var(--t-pink2); }

/* floating button: a small round stamp with a dotted (perforated) rim */
.mt-fab, .mt-fab.mt-fab-docked {
  background: radial-gradient(circle, var(--t-ink) 0 15px, var(--t-frame) 15.5px);
  border: 2.5px dotted var(--t-frame);
  border-radius: 50%;
  color: var(--t-frame);
  box-shadow: none;
}
.mt-fab:hover, .mt-fab.mt-fab-docked:hover { background: var(--t-pink); border-color: var(--t-pink); color: var(--t-ink); }

.mt-pl-modal-box { background: var(--t-pic); color: var(--t-frame); border: 10px solid var(--t-frame); border-radius: 0; box-shadow: none; }
.mt-pl-modal-track { color: #fff; font-weight: 700; }
.mt-pl-option { color: var(--t-frame); border: 1px solid var(--t-line2); border-radius: 0; background: transparent; }
.mt-pl-option:hover { background: color-mix(in srgb, var(--t-frame) 12%, transparent); border-color: var(--t-frame); }
.mt-pl-option.mt-is-added { background: var(--t-pink); color: var(--t-ink); border-color: var(--t-pink); }

/* settings: a big stamp */
#mt-settings-modal .mt-flex-container {
  background: var(--t-pic);
  color: var(--t-frame);
  border: 14px solid var(--t-frame);
  border-radius: 0;
  box-shadow: none;
  font-family: 'Old Standard TT', Georgia, serif;
  -webkit-mask: var(--t-perf);
  mask: var(--t-perf);
}
#mt-settings-modal .mt-header h3 { font-weight: 700; font-size: 1.4em; letter-spacing: 0.14em; text-transform: uppercase; color: var(--t-frame); }
#mt-settings-modal .mt-close { color: var(--t-frame); }
#mt-settings-modal .mt-close:hover { color: #fff; }
#mt-settings-modal .mt-subpanel { background: color-mix(in srgb, var(--t-frame) 5%, transparent); border: 1px solid var(--t-line2); border-radius: 0; }
#mt-settings-modal .mt-btn-test {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 6px;
  background: var(--t-pink);
  color: var(--t-ink);
  border: none;
  border-radius: 0;
  padding: 8px 14px;
  font-weight: 700;
  letter-spacing: 0.06em;
  cursor: pointer;
}
#mt-settings-modal .mt-btn-test:hover { background: var(--t-pink2); }
.mt-tag, .mt-genre-tag, .mt-mood-tag, .mt-scenario-tag { background: transparent; border: 1px solid var(--t-line); color: var(--t-frame); border-radius: 0; padding: 4px 10px; }
.mt-tag:hover, .mt-genre-tag:hover, .mt-mood-tag:hover, .mt-scenario-tag:hover { border-color: var(--t-frame); color: #fff; }
.mt-tag.active, .mt-genre-tag.active, .mt-mood-tag.active, .mt-scenario-tag.active { background: var(--t-pink); border-color: var(--t-pink); color: var(--t-ink); font-weight: 700; }

.mt-player ::-webkit-scrollbar, #mt-settings-modal ::-webkit-scrollbar, .mt-pl-modal-box ::-webkit-scrollbar { width: 5px; height: 5px; }
.mt-player ::-webkit-scrollbar-track, #mt-settings-modal ::-webkit-scrollbar-track, .mt-pl-modal-box ::-webkit-scrollbar-track { background: transparent; }
.mt-player ::-webkit-scrollbar-thumb, #mt-settings-modal ::-webkit-scrollbar-thumb, .mt-pl-modal-box ::-webkit-scrollbar-thumb { background: var(--t-frame); border-radius: 0; }

/* sizes and modes */
@container (max-width: 640px) { .mt-player.moodtube-row-layout .mt-volume { display: none; } }

.mt-player.moodtube-row-layout#moodtube-mini-player { padding: 30px 24px 24px; }
.mt-player.moodtube-row-layout#moodtube-mini-player .mt-player-header { top: 18px; }
.mt-player.moodtube-row-layout#moodtube-mini-player .mt-window-btn { top: 17px; }
.mt-player.moodtube-row-layout#moodtube-mini-player .mt-player-body { flex-direction: row; align-items: center; gap: 12px; padding-top: 6px; }
.mt-player.moodtube-row-layout#moodtube-mini-player .mt-track-info { min-width: 120px; max-width: 200px; flex: 0 1 180px; align-items: flex-start; text-align: left; padding: 0 22px 0 0; }
#moodtube-mini-player.moodtube-row-layout .mt-track-title { font-size: 16px; }
.mt-player.moodtube-row-layout#moodtube-mini-player .mt-progress { flex: 1 1 100px; min-width: 90px; }
.mt-player.moodtube-row-layout#moodtube-mini-player .mt-controls { gap: 5px; flex-shrink: 0; }
.mt-player.moodtube-row-layout#moodtube-mini-player .mt-controls > .mt-btn { width: 28px; height: 28px; font-size: 11px; }
.mt-player.moodtube-row-layout#moodtube-mini-player .mt-controls > .mt-btn.mt-btn-play,
.mt-player.moodtube-row-layout#moodtube-mini-player .mt-controls > #moodtube-btn-playpause { width: 34px; height: 34px; font-size: 13px; }
.mt-player.moodtube-row-layout#moodtube-mini-player .mt-volume { width: 76px; flex-shrink: 0; }
.mt-player.moodtube-row-layout .mt-slot-decor, .mt-player.moodtube-row-layout .mt-slot-scene::after { display: none; }

@container (max-width: 190px) {
  .mt-player .mt-controls { gap: 4px; }
  .mt-player .mt-controls > .mt-btn { width: 26px; height: 26px; font-size: 11px; }
  .mt-player .mt-controls > .mt-btn.mt-btn-play, .mt-player .mt-controls > #moodtube-btn-playpause { width: 30px; height: 30px; font-size: 12px; }
}

/* under the tavern header: no perforation on the wide panel, a plain frame instead */
#moodtube-mini-player.mt-player-docked {
  background: var(--t-pic);
  -webkit-mask: none;
  mask: none;
  border-top: 6px solid var(--t-frame);
}
#moodtube-mini-player.mt-player-docked .mt-slot-bg { inset: 0; }

#moodtube-dock { background: var(--t-ink); border-bottom: 3px dotted var(--t-frame); }
#moodtube-dock .mt-dock-title { font-family: 'Old Standard TT', Georgia, serif; font-weight: 700; font-size: 14px; letter-spacing: 0.08em; text-transform: uppercase; color: var(--t-title); }
#moodtube-dock .mt-dock-subtitle { font-family: 'Old Standard TT', Georgia, serif; font-size: 10px; letter-spacing: 0.2em; text-transform: uppercase; color: var(--t-alt); }
#moodtube-dock .mt-dock-inner .mt-dock-cover { border: 2px solid var(--t-frame); }

/* ===== Trick or Treat: blue stamp, the cover in a pink frame, a black cat peeking from behind it ===== */
.mt-player, #mt-settings-modal, .mt-fab, .mt-pl-modal, #moodtube-dock {
  --t-frame: #9fb4d6;
  --t-alt: #f2a8b8;
  --t-pic: #141014;
  --t-title: #f2a8b8;
}

/* "TRICK OR TREAT" stacked in the top left corner */
.mt-player-header-title { display: block; width: 52px; white-space: normal; font-size: 11px; font-weight: 700; line-height: 1.25; letter-spacing: 0.08em; color: var(--t-pink); overflow: visible; }

.mt-slot-scene::before { content: 'SPOOKY SEASON'; left: 0; right: 0; text-align: center; color: var(--t-pink); }

/* the cover: a picture in a pink frame */
.mt-cover {
  width: 104px;
  height: 104px;
  margin-bottom: 30px;
  box-sizing: border-box;
  border-radius: 3px;
  border: 5px solid var(--t-pink);
  box-shadow: none;
  background: var(--t-blue2);
}
img.mt-cover-img { border-radius: 0; object-fit: cover; filter: saturate(0.85); }
.mt-slot-cover { border-radius: 0; background: none; }
.mt-slot-cover-bg { border-radius: 0; background: radial-gradient(circle at 66% 34%, var(--t-pink) 0 15px, transparent 16px), var(--t-blue2); }

/* iron fence under the picture */
.mt-slot-scene::after {
  content: '';
  position: absolute;
  left: 14px;
  right: 14px;
  top: 150px;
  height: 24px;
  background: url("data:image/svg+xml,%3Csvg%20xmlns%3D%27http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg%27%20viewBox%3D%270%200%2024%2024%27%3E%3Cg%20fill%3D%27%239fb4d6%27%3E%3Crect%20y%3D%2720%27%20width%3D%2724%27%20height%3D%272%27%2F%3E%3Crect%20y%3D%2711%27%20width%3D%2724%27%20height%3D%271.5%27%2F%3E%3Cpath%20d%3D%27M11%2024V8l1-5%201%205v16z%27%2F%3E%3C%2Fg%3E%3C%2Fsvg%3E") 0 bottom / 24px 24px repeat-x;
}

/* the cat sits on the fence and peeks out from behind the right edge of the picture */
.mt-slot-decor {
  inset: auto;
  left: calc(50% + 40px);
  top: 96px;
  width: 44px;
  height: 58px;
