#moodtube-mini-player.moodtube-row-layout .mt-player-header-title { width: auto; white-space: nowrap; font-size: 11px; line-height: 1; }
.mt-player.moodtube-row-layout#moodtube-mini-player .mt-cover { width: 60px; height: 60px; margin: 0; border-width: 3px; }

